// BANNER SLIDER LOGIC
// =========================================================================
let currentBannerIdx = 0;
let bannerInterval = null;

function renderBanners(images) {
    const container = document.getElementById('homeBannerSliderContainer');
    if(!container) return;
    images = [window.PB_BANNER];
    container.innerHTML = images.map((src, i) => `<img src="${src}" class="slider-img ${i === 0 ? 'opacity-100' : 'opacity-0'}" id="slide-img-${i}">`).join('');
    
    if(bannerInterval) clearInterval(bannerInterval);
    if(images.length > 1) {
        bannerInterval = setInterval(() => {
            const oldImg = document.getElementById(`slide-img-${currentBannerIdx}`);
            if(oldImg) oldImg.classList.replace('opacity-100', 'opacity-0');
            currentBannerIdx = (currentBannerIdx + 1) % images.length;
            const newImg = document.getElementById(`slide-img-${currentBannerIdx}`);
            if(newImg) newImg.classList.replace('opacity-0', 'opacity-100');
        }, 3000);
    }
}

