function normalizeLoginPhone(value) {
    let p = String(value || '').trim().replace(/\s+/g, '');
    if (p.startsWith('+880')) p = p.substring(1);
    if (p.startsWith('8801') && p.length === 13) return p.substring(3);
    if (p.startsWith('01') && p.length === 11) return p;
    return p;
}

function getPhoneCandidates(value) {
    const raw = String(value || '').trim().replace(/\s+/g, '');
    const local = normalizeLoginPhone(raw);
    const candidates = [raw, local];
    if (local.startsWith('01') && local.length === 11) candidates.push('880' + local.substring(1));
    if (raw.startsWith('8801') && raw.length === 13) candidates.push('0' + raw.substring(3));
    if (raw.startsWith('+8801') && raw.length === 14) candidates.push('0' + raw.substring(4));
    return [...new Set(candidates.filter(Boolean))];
}

function loadUserAfterLogin(phoneKey) {
    localStorage.setItem('bd99_user', phoneKey);
    location.reload();
}

function handleAuth() {
    const rawPhone = document.getElementById('authPhone').value;
    const pass = document.getElementById('authPass').value;
    if(!rawPhone || !pass) return alert("Please fill all fields!");

    if(authMode === 'login') {
        const candidates = getPhoneCandidates(rawPhone);
        let checked = 0;
        let found = false;

        candidates.forEach(key => {
            if(found) return;
            database.ref('users/' + key).once('value').then(s => {
                checked++;
                if(found) return;
                if(s.exists() && String(s.val().pass) === String(pass)) {
                    found = true;
                    loadUserAfterLogin(key);
                    return;
                }
                if(checked === candidates.length && !found) {
                    // Fallback for accounts whose database key differs from the entered phone format.
                    database.ref('users').orderByChild('phone').equalTo(normalizeLoginPhone(rawPhone)).once('value').then(rs => {
                        let matchedKey = null;
                        rs.forEach(child => {
                            if(!matchedKey && child.val() && String(child.val().pass) === String(pass)) matchedKey = child.key;
                        });
                        if(matchedKey) loadUserAfterLogin(matchedKey);
                        else alert("Invalid Login Credentials!");
                    }).catch(err => {
                        console.error(err);
                        alert("Unable to check login. Please try again.");
                    });
                }
            }).catch(err => {
                console.error(err);
                checked++;
                if(checked === candidates.length && !found) alert("Unable to connect to the server. Please try again.");
            });
        });
    } else {
        const p = normalizeLoginPhone(rawPhone);
        const cPass = document.getElementById('authConfirmPass').value;
        const ref = document.getElementById('authInviteCode').value;
        if(pass !== cPass) return alert("Passwords do not match!");
        if(!/^01\d{9}$/.test(p)) return alert("Please enter a valid Bangladesh phone number.");

        database.ref('users/' + p).once('value').then(s => {
            if(s.exists()) return alert("Account already exists with this number!");
            const uid = Math.floor(100000 + Math.random() * 900000);
            const newUser = { 
                phone: p, pass: pass, uid: uid, balance: 75, deviceId: getDeviceId(), wager_left: 120, referrer: ref || null, joinDate: getStandardDateStr(new Date()), last_commission_date: getStandardDateStr(new Date()), referrals: { count: 0, depSum: 0, betSum: 0, commission: 0 }, giftHistory:[], betHistory:[], transactions:[{ type: 'Welcome Bonus', amount: 75, method: 'System', status: 'Complete', date: new Date().toLocaleString(), timestamp: Date.now(), orderNum: 'WB' + Date.now(), note: 'Registration Welcome Bonus 75 BDT' }], avatar: pickDefaultAvatar(uid), rebateClaimed: 0, safeBox: 0, claimedAwards: {}
            };
            if(ref) { database.ref('users').orderByChild('uid').equalTo(parseInt(ref)).once('value', rs => { if(rs.exists()) { rs.forEach(c => { let rKey = c.key; let cnt = c.val().referrals.count || 0; database.ref(`users/${rKey}/referrals/count`).set(cnt + 1); }); } }); }
            database.ref('users/' + p).set(newUser).then(() => { alert("Registered Successfully! 97 BDT Bonus Added. Please Login now."); toggleAuth('login'); }).catch(err => { console.error(err); alert("Registration failed. Please try again."); });
        }).catch(err => {
            console.error(err);
            alert("Unable to connect to the server. Please try again.");
        });
    }
}

