function setupListeners(phone) {
    database.ref('users/' + phone).on('value', s => {
        if(s.exists()) {
            user = s.val();
            if(!user.betHistory) user.betHistory =[]; if(!user.transactions) user.transactions =[]; if(!user.giftHistory) user.giftHistory =[];
            if(!user.avatar) user.avatar = pickDefaultAvatar(user.uid);
            if(user.wager_left === undefined) user.wager_left = 0;
            if(user.rebateClaimed === undefined) user.rebateClaimed = 0;
            if(user.safeBox === undefined) user.safeBox = 0;
            if(!user.claimedAwards) user.claimedAwards = {};
            
            let updates = {}; let needsUpdate = false;
            let txArr = Array.isArray(user.transactions) ? user.transactions : Object.values(user.transactions);
            
            txArr.forEach((t, idx) => {
                let st = String(t.status).toLowerCase();
                if(t.type === 'Deposit' && (st === 'accepted' || st === 'complete' || st === 'success') && !t.wagerAdded) {
                    user.wager_left = (parseFloat(user.wager_left) || 0) + parseFloat(t.amount);
                    t.wagerAdded = true; updates[`users/${user.phone}/wager_left`] = user.wager_left; updates[`users/${user.phone}/transactions/${idx}/wagerAdded`] = true; needsUpdate = true;
                }
            });
            if(needsUpdate) database.ref().update(updates);
            checkCommissionTransfer(); updateUI();
        }
    });
}

