    document.querySelectorAll('.safeBoxBalanceDisplay').forEach(e => e.innerText = parseFloat(user.safeBox || 0).toFixed(2));
    
    document.getElementById('profilePhone').innerText = user.name || user.phone; 
    document.getElementById('profileUID').innerText = user.uid; 
    if(!user.avatar || String(user.avatar).indexOf('dicebear') > -1) { user.avatar = pickDefaultAvatar(user.uid || user.phone); try { database.ref('users/' + user.phone + '/avatar').set(user.avatar); } catch(e) {} }
    document.getElementById('profileAvatarImg').src = user.avatar;
    document.querySelectorAll('.hdrAvatar').forEach(function(i){ i.src = user.avatar; });
    try { document.getElementById('profilePhone').innerText = user.phone || user.name; var _n = document.getElementById('profileNick'); if(_n) _n.innerText = user.name || user.phone; var _j = document.getElementById('profileJoined'); if(_j) _j.innerText = user.joinDate || '-'; } catch(e) {}
    
    let refLink = window.location.origin + window.location.pathname + "?ref=" + user.uid;
