function submitSafeBoxTransfer() {
    let amt = parseFloat(document.getElementById('safeBoxAmtInput').value);
    if(isNaN(amt) || amt <= 0) return alert("Please enter a valid amount");

    if (currentSafeBoxTab === 'in') {
        if(user.balance < amt) return alert("Insufficient Main Balance to save");
        user.balance -= amt;
        user.safeBox = (parseFloat(user.safeBox) || 0) + amt;
    } else {
        if((parseFloat(user.safeBox) || 0) < amt) return alert("Insufficient Safe Box Balance to take out");
        user.safeBox -= amt;
        user.balance += amt;
    }

    database.ref('users/' + user.phone).set(user).then(() => {
        alert("Transfer Successful!");
        document.getElementById('safeBoxAmtInput').value = '';
        updateUI();
    });
}

function openRebateModal() {
    if(!user || !user.betHistory) {
        document.getElementById('rebateTotalBetDisplay').innerText = "0.00";
        document.getElementById('rebateClaimableDisplay').innerText = "0.00";
        document.getElementById('rebateClaimBtn').disabled = true;
    } else {
        let betsArr = Array.isArray(user.betHistory) ? user.betHistory : Object.values(user.betHistory);
        let totalBet = 0;
        betsArr.forEach(b => totalBet += parseFloat(b.amount || 0));
        
        let totalEarnable = Math.floor(totalBet / 1000) * 6; // 6 Taka per 1000 Bet
        let alreadyClaimed = parseFloat(user.rebateClaimed || 0);
        let claimableNow = totalEarnable - alreadyClaimed;

        document.getElementById('rebateTotalBetDisplay').innerText = totalBet.toFixed(2);
        document.getElementById('rebateClaimableDisplay').innerText = claimableNow.toFixed(2);
        
        if (claimableNow > 0) {
            document.getElementById('rebateClaimBtn').disabled = false;
        } else {
            document.getElementById('rebateClaimBtn').disabled = true;
        }
    }
    document.getElementById('rebateModal').classList.remove('hidden-el');
}

function executeRebateClaim() {
    if(!user || !user.betHistory) return;
    let betsArr = Array.isArray(user.betHistory) ? user.betHistory : Object.values(user.betHistory);
    let totalBet = 0;
    betsArr.forEach(b => totalBet += parseFloat(b.amount || 0));
    
    let totalEarnable = Math.floor(totalBet / 1000) * 6;
    let alreadyClaimed = parseFloat(user.rebateClaimed || 0);
    let claimableNow = totalEarnable - alreadyClaimed;

    if(claimableNow > 0) {
        user.balance += claimableNow;
        user.rebateClaimed = alreadyClaimed + claimableNow;
        
        if(!user.transactions) user.transactions =[];
        let txArr = Array.isArray(user.transactions) ? user.transactions : Object.values(user.transactions);
        txArr.unshift({
            type: 'Betting Rebate',
            amount: claimableNow,
            method: 'System',
            status: 'Complete',
            date: new Date().toLocaleString(),
            timestamp: Date.now(),
            orderNum: 'REB' + Date.now(),
            note: 'Turnover Rebate Claimed'
        });
        user.transactions = txArr;
        database.ref('users/'+user.phone).set(user).then(() => {
            alert(`Successfully Claimed ৳${claimableNow} as Betting Rebate!`);
            openRebateModal();
            updateUI();
        });
    }
}

function openAwardModal() {
    renderAwardList();
    document.getElementById('awardModal').classList.remove('hidden-el');
}

function getTotalDepositAmount() {
    let totalDep = 0;
    if(user && user.transactions) {
        let txArr = Array.isArray(user.transactions) ? user.transactions : Object.values(user.transactions);
        txArr.forEach(t => {
            if (t.type === 'Deposit' && ['accepted','complete','success'].includes(String(t.status).toLowerCase())) {
                totalDep += parseFloat(t.amount || 0);
            }
        });
    }
    return totalDep;
}

function renderAwardList() {
    let totalDep = getTotalDepositAmount();
    document.getElementById('awardTotalDeposit').innerText = totalDep.toFixed(2);
    
    let html = '';
    let highestEligibleIndex = -1;
    for (let i = depositMilestones.length - 1; i >= 0; i--) {
        if (totalDep >= depositMilestones[i].dep) {
            highestEligibleIndex = i;
            break;
        }
    }

    depositMilestones.forEach((m, idx) => {
        let isClaimed = user.claimedAwards && user.claimedAwards[`award_${m.dep}`] === true;
        let btnHtml = '';
        if (isClaimed) {
            btnHtml = `<button class="px-4 py-2 bg-gray-200 text-gray-500 rounded-lg font-black text-[10px] uppercase tracking-wider cursor-not-allowed">CLAIMED</button>`;
        } else if (idx === highestEligibleIndex) {
            btnHtml = `<button onclick="claimDepositAward(${m.dep}, ${m.reward})" class="px-4 py-2 bg-[#4A8CD3] text-white rounded-lg font-black text-[10px] uppercase tracking-wider shadow-sm hover:scale-105 transition active:scale-95">CLAIM</button>`;
        } else if (idx < highestEligibleIndex) {
            btnHtml = `<button class="px-4 py-2 bg-red-100 border border-red-200 text-red-400 rounded-lg font-black text-[10px] uppercase tracking-wider cursor-not-allowed">SKIPPED</button>`;
        } else {
            btnHtml = `<button onclick="switchTab('wallet'); setWalletTab('deposit'); hideModal('awardModal');" class="px-4 py-2 bg-gray-100 border border-gray-200 text-gray-400 rounded-lg font-black text-[10px] uppercase tracking-wider hover:bg-gray-200 transition">GO DEP</button>`;
        }

        html += `
        <div class="bg-white rounded-xl p-4 flex justify-between items-center shadow-sm border border-gray-100">
            <div class="flex items-center gap-3">
                <div class="w-10 h-10 rounded-full bg-orange-50 text-orange-500 flex items-center justify-center text-lg"><i class="fas fa-medal"></i></div>
                <div>
                    <h4 class="text-xs font-black text-gray-800 uppercase tracking-wider mb-0.5">Dep ৳${m.dep}</h4>
                    <p class="text-[10px] text-gray-500 font-bold">Reward: <span class="text-orange-500 font-black">৳${m.reward}</span></p>
                </div>
            </div>
            ${btnHtml}
        </div>`;
    });
    
    document.getElementById('awardListContainer').innerHTML = html;
}

function claimDepositAward(depAmount, rewardAmount) {
    if (!user) return;
    let totalDep = getTotalDepositAmount();
    if (totalDep < depAmount) return alert("Not eligible yet!");
    if (user.claimedAwards && user.claimedAwards[`award_${depAmount}`] === true) return alert("Already claimed!");
    
    user.balance += rewardAmount;
    if(!user.claimedAwards) user.claimedAwards = {};
    user.claimedAwards[`award_${depAmount}`] = true;

    if(!user.transactions) user.transactions =[];
    let txArr = Array.isArray(user.transactions) ? user.transactions : Object.values(user.transactions);
    txArr.unshift({
        type: 'Deposit Bonus',
        amount: rewardAmount,
        method: 'System',
        status: 'Complete',
        date: new Date().toLocaleString(),
        timestamp: Date.now(),
        orderNum: 'AWARD' + Date.now(),
        note: `Award Claimed for Reaching ৳${depAmount} Deposit`
    });
    user.transactions = txArr;
    
    database.ref('users/'+user.phone).set(user).then(() => {
        alert(`Congratulations! You received ৳${rewardAmount} Deposit Bonus!`);
        renderAwardList();
        updateUI();
    });
}

