function checkPendingBetsAgainstHistory() {
    if(!user || !user.betHistory) return;
    let updated = false;
    let totalWin = 0;
    let totalLoss = 0;
    let betsArr = Array.isArray(user.betHistory) ? user.betHistory : Object.values(user.betHistory);
    
    betsArr.forEach(b => {
        if(b.status === 'PENDING' && (b.market || '30s') === currentMarket) {
            let result = historyData.find(h => String(h.period) === String(b.period));
            if(result) {
                let num = parseInt(result.num);
                let size = num >= 5 ? 'Big' : 'Small'; 
                let isRed = [0,2,4,6,8].includes(num); 
                let isGreen = [1,3,5,7,9].includes(num);
                
                let win = false; let mult = 0;
                if(String(b.selection) === String(num)) { win = true; mult = 9; } 
                else if(b.selection === size) { win = true; mult = 2; } 
                else if(b.selection === 'Green' && isGreen) { win = true; mult = (num === 5 ? 1.5 : 2); } 
                else if(b.selection === 'Red' && isRed) { win = true; mult = (num === 0 ? 1.5 : 2); } 
                else if(b.selection === 'Violet' && (num === 0 || num === 5)) { win = true; mult = 4.5; }
                
                if(win) { 
                    b.status = 'WIN'; 
                    b.wonAmt = b.amount * mult * 0.98; 
                    user.balance += b.wonAmt; 
                    totalWin += b.wonAmt; 
                } else { 
                    b.status = 'LOSS'; 
                    totalLoss += b.amount; 
                }
                updated = true;
            }
        }
    });

    if(updated) {
        user.betHistory = betsArr;
        database.ref('users/' + user.phone).set(user).catch(e => console.error(e));
        updateUI();
        if(!document.getElementById('gamePage').classList.contains('hidden-el')) {
            if(totalWin > 0) showResultPopup('win', totalWin, { loss: totalLoss });
            else if (totalLoss > 0) showResultPopup('loss', totalLoss);
        }
    }
}

function initTimer() {
    if(gameTimerInterval) clearInterval(gameTimerInterval);
    const tick = () => {
        const nowMs = new Date().getTime() + serverOffset; const bdTime = new Date(nowMs + 21600000);
        const y = bdTime.getUTCFullYear(); const m = String(bdTime.getUTCMonth() + 1).padStart(2, '0'); const d = String(bdTime.getUTCDate()).padStart(2, '0');
        const dateStr = `${y}${m}${d}`; const totalSeconds = (bdTime.getUTCHours() * 3600) + (bdTime.getUTCMinutes() * 60) + bdTime.getUTCSeconds();

        Object.keys(marketConfigs).forEach(marketKey => {
            const conf = marketConfigs[marketKey]; const periodIdx = Math.floor(totalSeconds / conf.interval) + 1; const periodId = `${dateStr}${conf.prefix}${String(periodIdx).padStart(4,'0')}`;
            
            if (currentLivePeriods[marketKey] !== 0 && periodId !== currentLivePeriods[marketKey]) { 
                processResult(marketKey, currentLivePeriods[marketKey]); 
            } 
            
            currentLivePeriods[marketKey] = periodId;
            
            if (marketKey === currentMarket) {
                document.getElementById('periodId').innerText = periodId;
                const rem = conf.interval - (totalSeconds % conf.interval);
                let minStr = Math.floor(rem / 60).toString().padStart(2, '0'); let secStr = (rem % 60).toString().padStart(2, '0');
                document.getElementById('t-min-1').innerText = minStr[0]; document.getElementById('t-min-2').innerText = minStr[1]; document.getElementById('t-sec-1').innerText = secStr[0]; document.getElementById('t-sec-2').innerText = secStr[1];
                
                if (rem <= 5 && rem > 0) { 
                    document.getElementById('bettingLockOverlay').classList.remove('hidden-el'); document.getElementById('countdown-digit-1').innerText = "0"; document.getElementById('countdown-digit-2').innerText = rem;
                    if(!isSoundMuted && !document.getElementById('gamePage').classList.contains('hidden-el')) { let audio = document.getElementById('tickSound'); audio.currentTime = 0; audio.play().catch(e => {}); }
                } else if (rem === 0) { 
                    document.getElementById('bettingLockOverlay').classList.remove('hidden-el'); document.getElementById('countdown-digit-1').innerText = "0"; document.getElementById('countdown-digit-2').innerText = "0"; 
                } else { 
                    document.getElementById('bettingLockOverlay').classList.add('hidden-el'); 
                }
            }
        });
    }; 
    tick(); gameTimerInterval = setInterval(tick, 1000);
}

function fetchHistory() { 
    if(historyRef) historyRef.off(); 
    historyRef = database.ref(`global_history/${currentMarket}`).limitToLast(50);
    historyRef.on('value', s => { 
        if(s.exists()) { 
            historyData = Object.values(s.val()).sort((a,b) => parseInt(b.period) - parseInt(a.period)); 
        } else { 
            historyData = []; 
        } 
        updateDisplayData(); 
        checkPendingBetsAgainstHistory(); 
    }); 
}

function updateDisplayData() {
    let displayData =[]; let activePeriod = currentLivePeriods[currentMarket];
    if(activePeriod && activePeriod !== 0) {
        let activeStr = String(activePeriod); let prefix = activeStr.substring(0, 10); let indexPart = parseInt(activeStr.substring(10)); 
        for(let i = 1; i <= 50; i++) {
            let currentIdx = indexPart - i; if (currentIdx <= 0) break; 
            let p = prefix + String(currentIdx).padStart(4, '0'); let dbRecord = historyData.find(x => x.period === p); 
            if(dbRecord) { displayData.push(dbRecord); } else { let seed = parseInt(p.substring(10)); let x = Math.sin(seed * 12.9898) * 43758.5453; let pseudoNum = Math.floor(Math.abs(x - Math.floor(x)) * 10); displayData.push({ period: p, num: pseudoNum, size: pseudoNum >= 5 ? 'Big' : 'Small' }); } 
        }
    } else { displayData = historyData.slice(0, 50); }
    processedDisplayData = displayData;
    let miniHtml = '';
    for(let i=0; i<5; i++) { if(displayData[i]) { let n = displayData[i].num; let bg = n===0||n===5 ? 'bg-purple-600' : (n%2===0 ? 'bg-red-500' : 'bg-green-500'); miniHtml += `<div class="w-5 h-5 rounded-full ${bg} flex items-center justify-center text-[10px] border border-white/20 font-black shadow-sm text-white">${n}</div>`; } }
    document.getElementById('recentBallsMini').innerHTML = miniHtml;
    if(!document.getElementById('globalHistoryContainer').classList.contains('hidden-el')) { renderHistory(); } else if (!document.getElementById('chartHistoryContainer').classList.contains('hidden-el')) { renderChart(); }
}

async function processResult(marketKey, targetPeriod) {
    try {
        const snap = await database.ref(`global_history/${marketKey}/${targetPeriod}`).once('value'); 
        if(snap.exists()) return; 
        
        let winningNum = 0; let forced = adminForcedResults[marketKey];
        if(forced !== null && forced !== "") { winningNum = parseInt(forced); } 
        else {
            const betsSnap = await database.ref(`live_bets/${marketKey}/${targetPeriod}`).once('value'); const bets = betsSnap.val();
            if (!bets) { winningNum = Math.floor(Math.random() * 10); } 
            else {
                let minPayout = Infinity; let bestNums =[];
                for(let i = 0; i <= 9; i++) {
                    let payout = 0; let size = i >= 5 ? 'Big' : 'Small'; let isRed =[0,2,4,6,8].includes(i); let isGreen =[1,3,5,7,9].includes(i); let isViolet = (i === 0 || i === 5);
                    payout += (parseFloat(bets[String(i)]) || 0) * 9; payout += (parseFloat(bets[size]) || 0) * 2;
                    if(isRed) payout += (parseFloat(bets['Red']) || 0) * (i === 0 ? 1.5 : 2); if(isGreen) payout += (parseFloat(bets['Green']) || 0) * (i === 5 ? 1.5 : 2); if(isViolet) payout += (parseFloat(bets['Violet']) || 0) * 4.5;
                    if (payout < minPayout) { minPayout = payout; bestNums =[i]; } else if (payout === minPayout) { bestNums.push(i); }
                }
                winningNum = bestNums[Math.floor(Math.random() * bestNums.length)];
            }
        }
        const size = winningNum >= 5 ? 'Big' : 'Small'; 
        database.ref(`global_history/${marketKey}/${targetPeriod}`).transaction((currentData) => { 
            if (currentData === null) return { period: targetPeriod, num: winningNum, size: size }; 
            return; 
        });
    } catch(e) { console.error("Error processing result:", e); }
}

