function confirmBet() {
    if (!requireDepositToPlay()) { hideModal('betConfirmModal'); return; }
    let amt = parseInt(document.getElementById('finalAmount').value);
    if(isNaN(amt) || amt < 1) { amt = 1; document.getElementById('finalAmount').value = 1; }
    if(user.balance < amt) {
        hideModal('betConfirmModal');
        return gmPopup({ icon: '💰', title: 'Insufficient Balance', msg: 'আপনার ব্যালেন্স যথেষ্ট নয়। অনুগ্রহ করে ডিপোজিট করুন।', ok: 'Deposit', cancel: 'Close', onOk: function() { closeGame(); switchTab('wallet'); setWalletTab('deposit'); } });
    }
    user.balance -= amt;
    let currentWager = parseFloat(user.wager_left || 0); currentWager -= amt; if(currentWager < 0) currentWager = 0; user.wager_left = currentWager;
    
    let activePeriod = currentLivePeriods[currentMarket];
    const bet = { market: currentMarket, period: activePeriod, selection: currentBet.type, amount: amt, status: 'PENDING', date: new Date().toISOString(), timestamp: Date.now() };
    
    if(!user.betHistory) user.betHistory =[]; let betsArr = Array.isArray(user.betHistory) ? user.betHistory : Object.values(user.betHistory); betsArr.unshift(bet); user.betHistory = betsArr;
    database.ref(`live_bets/${currentMarket}/${activePeriod}/${currentBet.type}`).transaction(v => (parseFloat(v)||0)+amt); 
    database.ref(`admin_live_bets/${currentMarket}/${activePeriod}`).push({ phone: user.phone, uid: user.uid, name: user.name || user.phone, selection: currentBet.type, amount: amt, timestamp: Date.now(), date: new Date().toISOString() });
    
    database.ref('users/' + user.phone).set(user); 
    hideModal('betConfirmModal'); renderMyHistory();
}

