function calculateChartStats(data) {
    let missing = Array(10).fill(0); let avgMissing = Array(10).fill(0); let frequency = Array(10).fill(0); let maxConsecutive = Array(10).fill(0); let currConsecutive = Array(10).fill(0); let lastSeenIndex = Array(10).fill(-1); let gapSum = Array(10).fill(0);
    for(let i = data.length - 1; i >= 0; i--) {
        let n = parseInt(data[i].num); frequency[n]++;
        for(let j = 0; j < 10; j++) { if(j === n) { currConsecutive[j]++; if(currConsecutive[j] > maxConsecutive[j]) maxConsecutive[j] = currConsecutive[j]; } else { currConsecutive[j] = 0; } }
        let periodIndex = (data.length - 1) - i; if(lastSeenIndex[n] !== -1) { gapSum[n] += (periodIndex - lastSeenIndex[n] - 1); } lastSeenIndex[n] = periodIndex;
    }
    let topIndex = data.length - 1;
    for(let j = 0; j < 10; j++) { if(lastSeenIndex[j] !== -1) { missing[j] = topIndex - lastSeenIndex[j]; avgMissing[j] = frequency[j] > 1 ? Math.floor(gapSum[j] / (frequency[j] - 1)) : missing[j]; } else { missing[j] = data.length; avgMissing[j] = data.length; } }
    return { missing, avgMissing, frequency, maxConsecutive };
}

function renderStatRow(title, arr, colorCls) { let h = `<div class="grid grid-cols-[1fr_repeat(10,1fr)] gap-1 text-center items-center py-1"><div class="text-left font-bold text-gray-500 text-[9px] uppercase tracking-wider">${title}</div>`; for(let i = 0; i < 10; i++) { h += `<div class="font-bold ${colorCls} text-[10px]">${arr[i]}</div>`; } h += `</div>`; return h; }

function renderChart() {
    if(processedDisplayData.length === 0) return;
    const stats = calculateChartStats(processedDisplayData);
    let statsHtml = `<div class="grid grid-cols-[1fr_repeat(10,1fr)] gap-1 text-center items-center mb-3 pb-3 border-b border-gray-100"><div class="text-left font-black text-gray-800 text-[10px] uppercase tracking-wider">Statistic</div>`; for(let i = 0; i < 10; i++) { statsHtml += `<div class="font-black text-gray-600 rounded-full border border-gray-200 w-[20px] h-[20px] mx-auto flex items-center justify-center text-[10px] bg-gray-50 shadow-sm">${i}</div>`; } statsHtml += `</div>`;
    statsHtml += renderStatRow('Missing', stats.missing, 'text-gray-400'); statsHtml += renderStatRow('Avg missing', stats.avgMissing, 'text-gray-500'); statsHtml += renderStatRow('Frequency', stats.frequency, 'text-[#4A8CD3]'); statsHtml += renderStatRow('Max consec.', stats.maxConsecutive, 'text-gray-400');
    document.getElementById('chartStats').innerHTML = statsHtml;

    const totalPages = Math.ceil(processedDisplayData.length / PAGE_SIZE) || 1;
    if(chartCurrentPage > totalPages) chartCurrentPage = totalPages;
    const startIdx = (chartCurrentPage - 1) * PAGE_SIZE; const pageData = processedDisplayData.slice(startIdx, startIdx + PAGE_SIZE);
    
    let rowsHtml = '';
    pageData.forEach(r => {
        let num = parseInt(r.num); let sizeClass = r.size === 'Big' ? 'bg-orange-500 text-white' : 'bg-blue-500 text-white'; let sizeLetter = r.size === 'Big' ? 'B' : 'S';
        rowsHtml += `<div class="grid grid-cols-[auto_1fr_auto] gap-2 items-center py-2.5 border-b border-gray-100"><div class="text-[10px] text-gray-500 font-mono w-[95px]">${r.period}</div><div class="grid grid-cols-10 gap-1 text-center relative z-10 w-full max-w-[200px] mx-auto">`;
        for(let i = 0; i < 10; i++) {
            if(i === num) { let bg = num===0||num===5 ? 'bg-purple-500' : (num%2===0 ? 'bg-red-500' : 'bg-green-500'); if(num===0) bg = 'bg-gradient-to-br from-red-500 to-purple-500'; if(num===5) bg = 'bg-gradient-to-br from-green-500 to-purple-500'; rowsHtml += `<div class="mx-auto w-[20px] h-[20px] rounded-full ${bg} text-white font-bold flex items-center justify-center text-[10px] shadow-sm chart-win-num">${i}</div>`; } 
            else { rowsHtml += `<div class="mx-auto w-[20px] h-[20px] rounded-full text-gray-300 flex items-center justify-center text-[10px] font-bold">${i}</div>`; }
        }
        rowsHtml += `</div><div class="w-5 h-5 rounded-sm flex items-center justify-center text-[10px] font-black ${sizeClass} shadow-sm">${sizeLetter}</div></div>`;
    });
    document.getElementById('chartRows').innerHTML = rowsHtml; document.getElementById('chartPageIndicator').innerText = `${chartCurrentPage}/50`;
    setTimeout(drawTrendLines, 50);
}

function drawTrendLines() {
    const canvas = document.getElementById('chartLineCanvas'); const drawBox = document.getElementById('chartDrawBox'); 
    if(!canvas || !drawBox) return; canvas.setAttribute('width', drawBox.offsetWidth); canvas.setAttribute('height', drawBox.offsetHeight);
    const winElements = document.querySelectorAll('.chart-win-num'); const boxRect = drawBox.getBoundingClientRect(); let svgHTML = '';
    for(let i = 0; i < winElements.length - 1; i++) {
        const el1 = winElements[i]; const el2 = winElements[i+1]; const rect1 = el1.getBoundingClientRect(); const rect2 = el2.getBoundingClientRect();
        const x1 = rect1.left - boxRect.left + (rect1.width / 2); const y1 = rect1.top - boxRect.top + (rect1.height / 2); const x2 = rect2.left - boxRect.left + (rect2.width / 2); const y2 = rect2.top - boxRect.top + (rect2.height / 2);
        svgHTML += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#4A8CD3" stroke-width="1.5" opacity="0.6" />`;
    }
    canvas.innerHTML = svgHTML;
}

