function checkCommissionTransfer() {
    if(!user || !user.referrals) return;
    if (parseFloat(user.referrals.commission) > 0) {
        const comm = parseFloat(user.referrals.commission); user.balance = (parseFloat(user.balance) || 0) + comm; user.referrals.commission = 0;
        if(!user.transactions) user.transactions =[]; let txArr = Array.isArray(user.transactions) ? user.transactions : Object.values(user.transactions);
        txArr.unshift({ type: 'Commission Bonus', amount: comm, method: 'System', status: 'Complete', date: new Date().toLocaleString(), timestamp: Date.now(), orderNum: 'COM' + Date.now() });
        user.transactions = txArr; database.ref('users/'+user.phone).set(user);
    }
}

function fetchPromoData() {
    database.ref('users').on('value', snap => {
        if(snap.exists()) {
            allUsersDataCache = snap.val();
            if(!document.getElementById('page-promotion').classList.contains('hidden-el')) { calculateAndRenderPromoStats(); }
        }
    });
}

function togglePromoTab(tab) { if(tab === 'direct') { document.getElementById('promo-tab-direct').className = "flex-1 py-3 text-[#4A8CD3] cursor-pointer border-b-2 border-[#4A8CD3]"; document.getElementById('promo-tab-team').className = "flex-1 py-3 text-gray-500 bg-gray-50 cursor-pointer border-b-2 border-transparent"; document.getElementById('promo-content-direct').classList.remove('hidden-el'); document.getElementById('promo-content-team').classList.add('hidden-el'); } else { document.getElementById('promo-tab-team').className = "flex-1 py-3 text-[#4A8CD3] cursor-pointer border-b-2 border-[#4A8CD3]"; document.getElementById('promo-tab-direct').className = "flex-1 py-3 text-gray-500 bg-gray-50 cursor-pointer border-b-2 border-transparent"; document.getElementById('promo-content-team').classList.remove('hidden-el'); document.getElementById('promo-content-direct').classList.add('hidden-el'); } }

function calculateAndRenderPromoStats() {
    if(!allUsersDataCache || !user) return;
    let targetDateStr = getStandardDateStr(new Date()); let yestDate = new Date(); yestDate.setDate(yestDate.getDate() - 1); let yestDateStr = getStandardDateStr(yestDate);
    let myUidStr = String(user.uid); let lv1 =[], lv2 =[], lv3 =[];
    Object.values(allUsersDataCache).forEach(u => { if(String(u.referrer) === myUidStr) lv1.push(u); }); let lv1Uids = lv1.map(u => String(u.uid));
    Object.values(allUsersDataCache).forEach(u => { if(lv1Uids.includes(String(u.referrer))) lv2.push(u); }); let lv2Uids = lv2.map(u => String(u.uid));
    Object.values(allUsersDataCache).forEach(u => { if(lv2Uids.includes(String(u.referrer))) lv3.push(u); });
    let allTeam =[...lv1, ...lv2, ...lv3];
    let dirReg = lv1.length, dirDepNum = 0, dirDepAmt = 0; let teamReg = allTeam.length, teamDepNum = 0, teamDepAmt = 0;

    lv1.forEach(u => { let hasDeposited = false; if(u.transactions) { let txs = Array.isArray(u.transactions) ? u.transactions : Object.values(u.transactions); txs.forEach(t => { if(t.type === 'Deposit' &&['accepted','complete','success'].includes(String(t.status).toLowerCase())) { dirDepAmt += parseFloat(t.amount); hasDeposited = true; } }); } if(hasDeposited) dirDepNum++; });
    allTeam.forEach(u => { let hasDeposited = false; if(u.transactions) { let txs = Array.isArray(u.transactions) ? u.transactions : Object.values(u.transactions); txs.forEach(t => { if(t.type === 'Deposit' &&['accepted','complete','success'].includes(String(t.status).toLowerCase())) { teamDepAmt += parseFloat(t.amount); hasDeposited = true; } }); } if(hasDeposited) teamDepNum++; });

    document.getElementById('st_dir_reg').innerText = dirReg; document.getElementById('st_dir_depNum').innerText = dirDepNum; document.getElementById('st_dir_depAmt').innerText = dirDepAmt.toFixed(2); 
    document.getElementById('st_team_reg').innerText = teamReg; document.getElementById('st_team_depNum').innerText = teamDepNum; document.getElementById('st_team_depAmt').innerText = teamDepAmt.toFixed(2); 

    let totalComm = 0; let yestComm = 0; let todayComm = 0;
    let todayStr = getStandardDateStr(new Date()); let y = new Date(); y.setDate(y.getDate() - 1); let yestStr = getStandardDateStr(y);

    if(user.transactions) { let txs = Array.isArray(user.transactions) ? user.transactions : Object.values(user.transactions); txs.forEach(t => { if(String(t.type).toLowerCase().includes('commission')) { let tDateStr = getStandardDateStr(new Date(t.timestamp || t.date)); let amt = parseFloat(t.amount) || 0; totalComm += amt; if(tDateStr === yestStr) yestComm += amt; if(tDateStr === todayStr) todayComm += amt; } }); }

    document.getElementById('yesterdayComm').innerText = yestComm.toFixed(2); document.getElementById('promo-this-week').innerText = todayComm.toFixed(2); document.getElementById('promo-total-comm').innerText = totalComm.toFixed(2); document.getElementById('promo-dir-sub').innerText = dirReg; document.getElementById('promo-total-sub').innerText = teamReg;
}

