function redeemGift() { 
    const code = document.getElementById('giftInputCode').value.trim(); if(!code) return; 
    database.ref('gift_codes/' + code).once('value', s => { 
        if(s.exists() && (s.val().active || s.val().status === 'active')) { 
            const data = s.val(); const maxLimit = data.maxLimit || 1; const claimedUsers = data.claimedUsers || {}; const claimedCount = Object.keys(claimedUsers).length;
            if (claimedUsers[user.phone]) return alert("You have already claimed this gift code!");
            if (claimedCount >= maxLimit) return alert("Gift code limit reached! Better luck next time.");
            const amt = parseFloat(data.amount); const noteText = data.note || 'Red envelope bonus'; 
            user.balance += amt; user.wager_left = (parseFloat(user.wager_left) || 0) + (amt * 2); 
            if(!user.giftHistory) user.giftHistory =[]; let gArr = Array.isArray(user.giftHistory) ? user.giftHistory : Object.values(user.giftHistory); 
            gArr.unshift({code, amount: amt, date: new Date().toLocaleString(), timestamp: Date.now(), note: noteText}); user.giftHistory = gArr; 
            if(!user.transactions) user.transactions =[]; let txArr = Array.isArray(user.transactions) ? user.transactions : Object.values(user.transactions);
            txArr.unshift({ type: 'Red envelope', amount: amt, method: 'Gift Code', status: 'Complete', date: new Date().toLocaleString(), timestamp: Date.now(), orderNum: 'GIFT' + Date.now(), note: noteText });
            user.transactions = txArr; claimedUsers[user.phone] = true; let updates = { claimedUsers: claimedUsers }; if (claimedCount + 1 >= maxLimit) { updates.active = false; updates.status = 'used'; }
            database.ref('gift_codes/' + code).update(updates); database.ref('users/' + user.phone).set(user); 
            alert("Claimed ৳" + amt); document.getElementById('giftInputCode').value = ""; renderGiftHistory(); updateUI(); 
        } else { alert("Invalid or Used Gift Code"); }
    }); 
}

function renderGiftHistory() { 
    if(!user) return; const list = document.getElementById('giftHistoryList'); let html = ''; 
    if(user.giftHistory) { let gArr = Array.isArray(user.giftHistory) ? user.giftHistory : Object.values(user.giftHistory); gArr.forEach(g => { html += `<div class="bg-gray-50 border border-gray-100 p-4 rounded-xl mb-3 flex justify-between items-center shadow-sm hover:shadow-md transition"><div><div class="text-xs font-black text-gray-800 mb-1 uppercase tracking-wider">Reward Claimed</div><div class="text-[10px] font-bold text-gray-400">${g.date}</div></div><div class="text-right flex items-center justify-end"><div class="text-[#4A8CD3] font-black text-sm bg-yellow-50 px-3 py-1.5 rounded shadow-sm border border-yellow-100"><i class="fas fa-wallet mr-2"></i> ${g.amount}</div></div></div>`; }); } 
    if(html === '') html = '<div class="text-center text-gray-400 text-xs mt-10 font-bold uppercase tracking-wider">No gifts claimed.</div>'; list.innerHTML = html; 
}

let chatListenerRef = null;
function openCsChat() {
    if(!user) return alert("Please login first to chat with support!");
    document.getElementById('csChatModal').classList.remove('hidden-el');
    if(chatListenerRef) chatListenerRef.off(); chatListenerRef = database.ref(`support_chats/${user.phone}/messages`);
    chatListenerRef.on('value', snap => {
        const body = document.getElementById('csChatBody'); body.innerHTML = '';
        if(snap.exists()) {
            const msgs = Object.values(snap.val()).sort((a,b)=>a.timestamp - b.timestamp);
            msgs.forEach(m => {
                const isMe = m.sender === 'user'; const time = new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
                let contentHtml = m.type === 'image' ? `<img src="${m.content}" class="max-w-[200px] rounded-lg cursor-pointer border border-black/10 shadow-sm" onclick="window.open('${m.content}')">` : `<p class="text-[13px] font-bold whitespace-pre-wrap">${m.content}</p>`;
                if(isMe) { body.innerHTML += `<div class="flex justify-end"><div class="max-w-[75%] bg-[#4A8CD3] text-white rounded-2xl rounded-tr-sm p-3 shadow-sm">${contentHtml}<span class="text-[9px] font-black opacity-70 block text-right mt-1">${time}</span></div></div>`; } 
                else { body.innerHTML += `<div class="flex justify-start"><div class="max-w-[75%] bg-white border border-gray-200 text-gray-800 rounded-2xl rounded-tl-sm p-3 shadow-sm">${contentHtml}<span class="text-[9px] font-black opacity-40 block text-left mt-1">${time}</span></div></div>`; }
            });
            setTimeout(() => { body.scrollTop = body.scrollHeight; }, 100);
        } else { body.innerHTML = `<div class="text-center text-gray-400 font-bold text-sm mt-10 uppercase tracking-widest"><i class="fas fa-headset text-4xl mb-4 block text-gray-300"></i>How can we help you?</div>`; }
    });
}
function closeCsChat() { document.getElementById('csChatModal').classList.add('hidden-el'); if(chatListenerRef) chatListenerRef.off(); }
function sendCsText() { const inp = document.getElementById('csTextInput'); const txt = inp.value.trim(); if(!txt) return; inp.value = ''; pushCsMessage('text', txt); }
async function sendCsImage(input) {
    if(!input.files || input.files.length === 0) return; const file = input.files[0]; const maxSize = 5 * 1024 * 1024; if(file.size > maxSize) return alert("Image too large! Maximum 5MB."); pushCsMessage('text', '[Uploading image...]');
    try { const ext = file.name.split('.').pop(); const fileName = `cs_${user.phone}_${Date.now()}.${ext}`; const storageRef = storage.ref(`support_images/${fileName}`); await storageRef.put(file); const url = await storageRef.getDownloadURL(); pushCsMessage('image', url); } 
    catch(e) { console.error(e); alert("Image upload failed"); } input.value = '';
}
function pushCsMessage(type, content) {
    const msg = { sender: 'user', type: type, content: content, timestamp: Date.now() }; database.ref(`support_chats/${user.phone}/messages`).push(msg);
    database.ref(`support_chats/${user.phone}/userInfo`).update({ uid: user.uid, phone: user.phone, name: user.name || user.phone, lastMessageTime: Date.now(), unreadByAdmin: true });
}

