P.forEach(p=>{$('ap'+p.i).onclick=function(){if(!this.classList.contains('on')&&!requireDepositToPlay())return;this.classList.toggle('on');p.auto=this.classList.contains('on')};$('ac'+p.i).onclick=function(){this.classList.toggle('on');p.autoOut=this.classList.contains('on')};$('ao'+p.i).oninput=function(){p.outAt=Math.max(1.01,+this.value||2)}});
function render(p){const b=$('b'+p.i);b.className='bb';
 if(phase=='fly'&&p.active){b.classList.add('out');b.innerHTML=`Cash Out<b>${fmt(p.amt*mval)} <small>BDT</small></b>`}
 else if(p.queued||(p.active&&phase!='fly')){b.classList.add('can');b.innerHTML=`<span>${phase=='fly'?'Waiting for next round':'Cancel'}</span>`;if(phase=='fly')b.innerHTML='Cancel<br><span>Waiting for next round</span>'}
 else b.innerHTML=`Bet<b>${fmt(p.amt)} <small>BDT</small></b>`}
P.forEach(p=>{$('b'+p.i).onclick=()=>{
 if(phase=='fly'&&p.active){cash(p);return}
 if(p.queued||(p.active&&phase=='wait')){if(p.active)setBalance(getBalance()+p.amt);p.active=false;p.queued=false;render(p);return}
 if(!requireDepositToPlay())return;
 if(getBalance()<p.amt){toast('Insufficient balance');return}
 if(phase=='wait'){setBalance(getBalance()-p.amt);p.active=true}else p.queued=true;render(p)}});

function cash(p){if(!p.active||phase!='fly')return;const w=p.amt*mval;setBalance(getBalance()+w);p.active=false;myHist.push(`${new Date().toLocaleTimeString()} — Bet ${fmt(p.amt)} × ${mval.toFixed(2)} = ${fmt(w)}`);toast(`<span style="color:#9f9">You have cashed out!</span> &nbsp; ${mval.toFixed(2)}x &nbsp; Win ${fmt(w)} BDT`);render(p)}

// simulated players
let rows=[],prevRows=[],totalBets=0;
function genRows(){const n=30+Math.random()*20|0;rows=[];for(let k=0;k<n;k++){const b=+(10+Math.pow(Math.random(),3)*9000).toFixed(2),k2=Math.random()*EM.length|0;rows.push({n:mask(),b,k:k2,x:+(1.05+Math.pow(Math.random(),2.2)*9).toFixed(2),won:false})}
 rows.sort((a,b)=>b.b-a.b);totalBets=2000+Math.random()*2500|0;$('bc').textContent='0/'+totalBets+' Bets'}
let tab='all';
R.querySelectorAll('.bt div').forEach(d=>d.onclick=()=>{R.querySelectorAll('.bt div').forEach(x=>x.classList.toggle('on',x===d));tab=d.dataset.t;drawList()});
function drawList(){let r=tab=='all'?rows:tab=='prev'?prevRows:[...prevRows].filter(x=>x.won).sort((a,b)=>b.b*b.x-a.b*a.x);
 $('list').innerHTML=r.slice(0,14).map(x=>`<div class="tr ${x.won?'w':''}"><div class="n"><i style="background-image:url('${playerAvatar(x.k)}')"></i>${x.n}</div><div class="b">${fmt(x.b)}</div><div class="x ${x.won?cc(x.x):''}">${x.won?x.x.toFixed(2)+'x':''}</div><div class="m">${x.won?fmt(x.b*x.x):''}</div></div>`).join('')}

// game loop
let raf=0,running=false;
let phase='wait',mval=1,crash=2,t0=0,tw=0,tc=0,pts=[];
function genCrash(){let c;
 if(typeof aviatorForcedCrash!=='undefined'&&aviatorForcedCrash!==null&&!isNaN(parseFloat(aviatorForcedCrash))){c=Math.max(1,parseFloat(aviatorForcedCrash));aviatorForcedCrash=null;
  const fd=document.getElementById('admin-aviator-forced-display'),st=document.getElementById('admin-aviator-status');if(fd)fd.innerText='Random';if(st){st.innerText='Status: Random Mode';st.style.color='#d0021b'}}
 else{const r=Math.random();c=Math.max(1,Math.floor(100*0.97/(1-r))/100)}
 return c}
function startWait(){phase='wait';$('glow').style.display='none';tw=performance.now();genRows();avs($('ava'));avs($('ava2'));P.forEach(p=>{if(p.queued){p.queued=false;if(getBalance()>=p.amt){setBalance(getBalance()-p.amt);p.active=true}}else if(p.auto&&hasSuccessfulDeposit()&&getBalance()>=p.amt){setBalance(getBalance()-p.amt);p.active=true}render(p)});$('tw').textContent='0.00';$('pbar').style.width='0';drawList();$('load').style.display='flex';$('mult').innerHTML='';pts=[]}
function startFly(){phase='fly';t0=performance.now();$('load').style.display='none';$('glow').style.display='block';crash=genCrash()}
function doCrash(){phase='crash';$('glow').style.display='none';tc=performance.now();hist.unshift(crash);hist=hist.slice(0,30);drawHist();
 P.forEach(p=>{if(p.active){myHist.push(`${new Date().toLocaleTimeString()} — Bet ${fmt(p.amt)} lost (${crash.toFixed(2)}x)`);p.active=false}render(p)});
 prevRows=rows.map(r=>({...r,won:r.x<crash&&r.won}));rows=prevRows;
 $('mult').innerHTML=`<small>FLEW AWAY!</small><span style="color:#e50539">${crash.toFixed(2)}x</span>`}
function loop(now){
 if(phase=='wait'){const e=(now-tw)/5000;$('lp').style.width=(100-e*100)+'%';$('pc').textContent=(1000+Math.random()*2000|0).toLocaleString('en-US');if(e>=1)startFly()}
 else if(phase=='fly'){const t=(now-t0)/1000;mval=Math.exp(0.1*t);
  if(mval>=crash){mval=crash;doCrash()}else{
  $('mult').innerHTML=`<span>${mval.toFixed(2)}x</span>`;{const ad=document.getElementById('admin-aviator-mult-display');if(ad)ad.innerText=mval.toFixed(2)+'x'}
  rows.forEach(r=>{if(!r.won&&r.x<=mval&&Math.random()<.2)r.won=true});
  let tot=0,wc=0;rows.forEach(r=>{if(r.won){tot+=r.b*r.x;wc++}});$('tw').textContent=fmt(tot*40);$('bc').textContent=Math.round(wc*totalBets/rows.length)+'/'+totalBets+' Bets';$('pbar').style.width=(wc/rows.length*100)+'%';$('pc').textContent=Math.max(0,(1500-t*30)|0).toLocaleString('en-US');
  if(Math.random()<.12)drawList();
  P.forEach(p=>{if(p.active){if(p.autoOut&&mval>=p.outAt)cash(p);else render(p)}})}}
 else if(phase=='crash'){if(now-tc>3000)startWait()}
 draw(now);if(running)raf=requestAnimationFrame(loop)}

const PLN=new Image();PLN.src='data:image/png;base64,';
function drawPlane(x,y,rot,now){if(!PLN.complete||!PLN.naturalWidth)return;const w=300,k=w/PLN.naturalWidth,h=PLN.naturalHeight*k;
 ctx.save();ctx.translate(x,y);ctx.rotate(rot);ctx.translate(-w*0.62,-h*0.55);ctx.drawImage(PLN,0,0,w,h);
 const hx=480*k,hy=101*k,bl=104*k,ph=Math.abs(Math.cos(now/45)),sg=Math.sin(now/45);
 ctx.fillStyle='#e50019';
 ctx.beginPath();ctx.ellipse(hx-4*k,hy,22*k,34*k,0,0,6.3);ctx.fill();
 ctx.save();ctx.translate(hx,hy);ctx.rotate(0.12);
 ctx.beginPath();ctx.ellipse(0,0,15*k,(8+bl/k*ph)*k,0,0,6.3);ctx.fill();
 ctx.beginPath();ctx.ellipse(0,0,15*k,(8+bl/k*Math.abs(sg))*k,0,0,6.3);ctx.globalAlpha=.55;ctx.fill();ctx.restore();
 ctx.restore()}
function draw(now){ctx.clearRect(0,0,W,H);const d=2;
 if(phase=='wait'){drawPlane(130*d,H-70*d+Math.sin(now/300)*4*d,-0.08,now);return}
 const t=phase=='fly'?(now-t0)/1000:Math.log(crash)/0.1;
 const tx=Math.max(t,6),my=Math.max(Math.exp(0.1*t),2.2);
 const px=60*d,py=H-40*d,ex=W-90*d,ey=130*d;
 const X=s=>px+(s/tx)*(ex-px)*(0.5+0.5*Math.min(1,t/tx)*1),Y=m=>py-((m-1)/(my-1))*(py-ey)*0.9;
 const N=60,xs=[],ys=[];for(let k=0;k<=N;k++){const s=t*k/N;xs.push(px+(s/tx)*(ex-px));ys.push(Y(Math.exp(0.1*s)))}
 const ramp=phase=='fly'?Math.min(1,Math.max(0,(t-6)/2.5)):0;
 const bob=Math.sin(now/650)*55*d*ramp,tilt=Math.cos(now/650)*0.22*ramp;
 for(let k=0;k<=N;k++){const f=k/N;ys[k]+=bob*f*f*f}
 let lx=xs[N],ly=ys[N];
 if(phase=='crash'){lx+= (now-tc)*0.6*d;ly-=(now-tc)*0.4*d}
 // fill
 const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'rgba(229,5,57,.45)');g.addColorStop(1,'rgba(120,0,30,.35)');
 if(phase=='fly'){ctx.beginPath();ctx.moveTo(xs[0],py);xs.forEach((x,k)=>ctx.lineTo(x,ys[k]));ctx.lineTo(lx,py);ctx.closePath();ctx.fillStyle=g;ctx.fill();
  ctx.beginPath();xs.forEach((x,k)=>k?ctx.lineTo(x,ys[k]):ctx.moveTo(x,ys[k]));ctx.strokeStyle='#e50539';ctx.lineWidth=7*d;ctx.stroke()}
 // plane
 if(!(phase=='crash'&&lx>W+100))drawPlane(lx,ly-6*d,-0.12-tilt,now)}

