function loadAdminNumbers() {
    try { if(window.buildAppConfigForm) window.buildAppConfigForm(); } catch(e) {}
    try {
        const b = document.getElementById('admNumBkash'), n = document.getElementById('admNumNagad');
        if(b) b.value = (depositNumbers && depositNumbers.Bkash) || ''; if(n) n.value = (depositNumbers && depositNumbers.Nagad) || '';
        const st = document.getElementById('admNumStatus'); if(st) st.innerText = 'Current numbers loaded';
    } catch(e) { console.error(e); }
}
function saveAdminNumbers() {
    const b = document.getElementById('admNumBkash').value.replace(/[\s-]/g,''); const n = document.getElementById('admNumNagad').value.replace(/[\s-]/g,'');
    const ok = v => /^\+?[0-9]{8,15}$/.test(v);
    if(!ok(b) || !ok(n)) return alert('সঠিক bKash ও Nagad নাম্বার দিন (শুধু সংখ্যা)।');
    const st = document.getElementById('admNumStatus'); st.innerText = 'Saving...';
    database.ref('admin_settings/payment_numbers').set({ Bkash: b, Nagad: n, updatedAt: Date.now() })
        .then(() => { depositNumbers = { Bkash: b, Nagad: n }; st.innerText = '✅ Saved — deposit page এ নতুন নাম্বার দেখাবে'; })
        .catch(err => { console.error(err); st.innerText = '❌ Save failed: ' + (err.message || err); });
}
function switchAdminTab(tab) {
    if(tab === 'wallet') loadAdminNumbers();
    document.getElementById('admin-wingo-panel').style.display = tab === 'wingo' ? 'block' : 'none';
    document.getElementById('admin-aviator-panel').style.display = tab === 'aviator' ? 'block' : 'none';
    document.getElementById('admin-wallet-panel').style.display = tab === 'wallet' ? 'block' : 'none';
    document.getElementById('admin-tab-wingo').style.background = tab === 'wingo' ? '#4A8CD3' : '#222';
    document.getElementById('admin-tab-wingo').style.color = tab === 'wingo' ? '#000' : '#aaa';
    document.getElementById('admin-tab-aviator').style.background = tab === 'aviator' ? '#d0021b' : '#222';
    document.getElementById('admin-tab-aviator').style.color = tab === 'aviator' ? '#fff' : '#aaa';
    document.getElementById('admin-tab-wallet').style.background = tab === 'wallet' ? '#16a34a' : '#222';
    document.getElementById('admin-tab-wallet').style.color = tab === 'wallet' ? '#fff' : '#aaa';
    if (tab === 'wingo') {
        const pd = document.getElementById('periodDisplay'); const tm = document.getElementById('timerDisplay');
        if (pd) document.getElementById('admin-wingo-period').innerText = pd.innerText;
        if (tm) document.getElementById('admin-wingo-timer-display').innerText = tm.innerText;
    }
    if (tab === 'wallet') loadAdminWallets();
}

let adminWalletType = 'Deposit';
let adminWalletStatus = 'Pending';
function adminWalletFilter(status) {
    adminWalletStatus = status;
    document.querySelectorAll('#admin-wallet-panel button').forEach(b => { if (['Pending','Accepted','Rejected'].includes(b.innerText)) { b.style.background = b.innerText === status ? '#4A8CD3' : '#333'; b.style.color = b.innerText === status ? '#000' : '#fff'; }});
    loadAdminWallets();
}
function loadAdminWallets() {
    const list = document.getElementById('admin-wallet-list');
    const summary = document.getElementById('admin-wallet-summary');
    if (!list) return;
    list.innerHTML = '<div style="text-align:center;color:#aaa;padding:25px;">Loading...</div>';
    database.ref('users').once('value').then(snap => {
        const users = snap.val() || {}; let rows = [];
        Object.keys(users).forEach(phone => {
            const u = users[phone] || {}; const txs = Array.isArray(u.transactions) ? u.transactions : Object.values(u.transactions || {});
            txs.forEach((t, idx) => {
                if (String(t.type) === adminWalletType && String(t.status || 'Pending').toLowerCase() === adminWalletStatus.toLowerCase()) rows.push({phone,u,t,idx});
            });
        });
        rows.sort((a,b) => (b.t.timestamp||0) - (a.t.timestamp||0));
        summary.innerText = adminWalletType + ' • ' + adminWalletStatus + ' • ' + rows.length + ' request(s)';
        if (!rows.length) { list.innerHTML = '<div style="text-align:center;color:#777;padding:30px;background:#151515;border-radius:10px;">No requests found.</div>'; return; }
        list.innerHTML = rows.map((r,i) => {
            const t=r.t,u=r.u; const action = String(t.status||'Pending').toLowerCase()==='pending' ? `<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:10px;"><button onclick="adminUpdateTransaction('${encodeURIComponent(r.phone)}',${r.idx},'Accepted')" style="background:#16a34a;color:#fff;border:0;border-radius:7px;padding:9px;font-weight:900;cursor:pointer;">✓ Accept</button><button onclick="adminUpdateTransaction('${encodeURIComponent(r.phone)}',${r.idx},'Rejected')" style="background:#dc2626;color:#fff;border:0;border-radius:7px;padding:9px;font-weight:900;cursor:pointer;">✕ Reject</button></div>` : '';
            return `<div style="background:#1a1a1a;border:1px solid #333;border-radius:10px;padding:12px;margin-bottom:8px;"><div style="display:flex;justify-content:space-between;gap:8px;"><b style="color:#4A8CD3;">${t.type} ৳${parseFloat(t.amount||0).toFixed(2)}</b><span style="color:#aaa;font-size:11px;">${t.date||''}</span></div><div style="font-size:12px;color:#ddd;margin-top:7px;">Phone: ${u.phone||r.phone}</div><div style="font-size:12px;color:#aaa;margin-top:4px;">Method: ${t.method||'-'} ${t.channel?'• '+t.channel:''}</div><div style="font-size:12px;color:#aaa;margin-top:4px;word-break:break-all;">TrxID: ${t.trx||'-'} • Order: ${t.orderNum||'-'}</div>${t.type==='Withdraw'&&u.wallet?`<div style="font-size:12px;color:#aaa;margin-top:4px;">Wallet: ${u.wallet.type||''} ${u.wallet.num||''}</div>`:''}${action}</div>`;
        }).join('');
    }).catch(err => { list.innerHTML = '<div style="color:#f87171;padding:20px;">Firebase read failed: '+(err.message||err)+'</div>'; });
}
function adminUpdateTransaction(phoneEncoded, idx, newStatus) {
    const phone = decodeURIComponent(phoneEncoded);
    database.ref('users/' + phone).once('value').then(snap => {
        const u=snap.val(); if(!u) throw new Error('User not found');
        const txs=Array.isArray(u.transactions)?u.transactions:Object.values(u.transactions||{}); const t=txs[idx];
        if(!t || String(t.status||'Pending').toLowerCase()!=='pending') return loadAdminWallets();
        if(t.type==='Deposit' && newStatus==='Accepted') u.balance=(parseFloat(u.balance)||0)+(parseFloat(t.amount)||0);
        if(t.type==='Withdraw' && newStatus==='Rejected') u.balance=(parseFloat(u.balance)||0)+(parseFloat(t.amount)||0);
        t.status=newStatus; t.adminUpdatedAt=Date.now(); t.adminNote='Processed by admin'; u.transactions=txs;
        return database.ref('users/'+phone).set(u);
    }).then(() => { alert('Transaction '+newStatus+'.'); loadAdminWallets(); }).catch(err => alert('Update failed: '+(err.message||err)));
}

