function openProfitLoss(){
  var bets = (user && user.betHistory) ? (Array.isArray(user.betHistory) ? user.betHistory : Object.values(user.betHistory)) : [];
  var wagered=0, won=0, lost=0, wins=0, losses=0;
  bets.forEach(function(b){
    var amt = parseFloat(b.amount)||0;
    if(b.status==='WIN'){ wins++; wagered+=amt; won+=(parseFloat(b.wonAmt)||0); }
    else if(b.status==='PENDING'){ }
    else { losses++; wagered+=amt; lost+=amt; }
  });
  var net = won - lost, done = wins+losses;
  var rate = done ? ((wins/done)*100).toFixed(1) : '0.0';
  var row = function(l,v,c){ return '<div class="acc-pl-row"><span style="color:#5B7B9A;font-weight:600">'+l+'</span><span style="font-weight:900;color:'+(c||'#00305F')+'">'+v+'</span></div>'; };
  document.getElementById('fullHistoryTitle').innerText = 'Profit And Loss';
  document.getElementById('fullHistoryContent').innerHTML =
    '<div class="acc-pl-card">'+
      row('Total Bets', bets.length)+
      row('Total Wagered','৳'+wagered.toFixed(2))+
      row('Total Won','+৳'+won.toFixed(2),'#4ade80')+
      row('Total Lost','-৳'+lost.toFixed(2),'#f87171')+
      row('Win Rate', rate+'%','#4A8CD3')+
      row('Net Profit / Loss', (net>=0?'+':'-')+'৳'+Math.abs(net).toFixed(2), net>=0?'#4ade80':'#f87171')+
    '</div>';
  document.getElementById('fullHistoryModal').classList.remove('hidden-el');
}
