function avUpload(inp){
  var f = inp.files && inp.files[0]; if(!f) return;
  var rd = new FileReader();
  rd.onload = function(e){
    var im = new Image();
    im.onload = function(){
      var c = document.createElement('canvas'); c.width = 128; c.height = 128;
      var side = Math.min(im.width, im.height), sx = (im.width - side)/2, sy = (im.height - side)/2;
      c.getContext('2d').drawImage(im, sx, sy, side, side, 0, 0, 128, 128);
      _avPending = c.toDataURL('image/jpeg', 0.8); avRender();
    };
    im.src = e.target.result;
  };
  rd.readAsDataURL(f); inp.value = '';
}

