function wdInfo(){
  var left=Math.max(0,CFG.WD_DAILY-todayCount()), b=bal(), left2=parseFloat((user&&user.wager_left)||0);
  $('wdDaily').innerHTML='Daily withdrawal '+CFG.WD_DAILY+' (Times), Remaining withdrawal '+left+' (Times)';
  $('wdMain').textContent=b.toFixed(2);
  $('wdAvail').textContent=(left2>0?0:b).toFixed(2);
  $('wdAmt').placeholder=CFG.WD_MIN+' ~ '+CFG.WD_MAX.toLocaleString('en-US');
}
window.wdChk=function(){
  var ok = getW(wd.m).length>0 && parseFloat($('wdAmt').value)>0 && $('wdPass').value.length>0;
  $('wdSubmit').disabled=!ok;
};
function wdRender(){ wdTabs(); wdBound(); wdInfo(); wdChk(); }
window.wdMethod=function(m){ wd.m=m; wdRender(); };
window.wdSelect=function(i){ wd.sel[wd.m]=i; wdBound(); };
window.wdDel=function(i){
  if(!confirm('Remove this E-wallet?')) return;
  var ws=getW(wd.m); var gone=ws.splice(i,1)[0];
  user.wallets[wd.m]=ws; if(!ws.length) delete user.wallets[wd.m];
  if(user.wallet && gone && user.wallet.type===wd.m && String(user.wallet.num)===String(gone.num)){
    var alt=null; WM.forEach(function(m){ var a=getW(m); if(!alt&&a.length) alt={type:m,num:a[0].num}; });
    if(alt) user.wallet=alt; else delete user.wallet;
  }
  wd.sel[wd.m]=0; database.ref('users/'+user.phone).set(user); wdRender(); toast('Removed');
};
window.wdAdd=function(){
  if(getW(wd.m).length>=CFG.MAX_WALLETS) return toast('Maximum '+CFG.MAX_WALLETS+' wallets allowed');
  lkOpen(wd.m);
};
window.wdGo=function(){
  if(busy||!user) return;
  var ws=getW(wd.m), w=ws[wd.sel[wd.m]||0];
  if(!w) return toast('Please link an E-wallet first');
  var amt=parseFloat($('wdAmt').value);
  if(isNaN(amt)||amt<CFG.WD_MIN||amt>CFG.WD_MAX) return toast('Withdrawal amount: '+CFG.WD_MIN+' ~ '+CFG.WD_MAX.toLocaleString('en-US'));
  if(bal()<amt) return toast('Low Balance');
  var left=parseFloat(user.wager_left||0); if(left>0) return toast('Turnover Pending! You must bet ৳'+left.toFixed(2)+' more to withdraw.');
  if(todayCount()>=CFG.WD_DAILY) return toast('Daily withdrawal limit reached');
  var pw=$('wdPass').value; var ok=user.txPass ? pw===String(user.txPass) : pw===String(user.pass);
  if(!ok) return toast('Incorrect transaction password');
  busy=true;
  user.wallet={type:wd.m,num:w.num};
  user.balance=bal()-amt;
  if(!user.transactions) user.transactions=[]; var txArr=Array.isArray(user.transactions)?user.transactions:Object.values(user.transactions);
  var orderNum='WD'+Date.now()+Math.floor(Math.random()*1000);
  txArr.unshift({type:'Withdraw',amount:amt,method:wd.m,status:'Pending',date:new Date().toLocaleString(),timestamp:Date.now(),orderNum:orderNum});
  user.transactions=txArr;
  database.ref('withdraw_requests').push({phone:user.phone,uid:user.uid,amount:amt,method:wd.m,number:w.num,name:w.name||'',status:'Pending',date:new Date().toLocaleString(),timestamp:Date.now()});
  database.ref('users/'+user.phone).set(user);
  $('wdAmt').value=''; $('wdPass').value=''; wdRender();
  toast('Withdraw Request Sent!'); showHistoryModal('Withdraw');
  setTimeout(function(){ busy=false; },800);
};

/* ================= LINK E-WALLET ================= */
var lk={m:'Nagad'};
function lkOpen(m){
  lk.m=m||wd.m; $('lkName').value=''; $('lkNum').value=''; $('lkP1').value=''; $('lkP2').value='';
  lkRender(); show('linkWalletPage');
}
function lkRender(){
  var h=''; WM.forEach(function(m){ h+='<div class="lk-g'+(lk.m===m?' on':'')+'" onclick="lkGroup(\''+m+'\')"><img src="'+logo(m,1)+'"></div>'; });
  $('lkGroups').innerHTML=h;
  $('lkChip').textContent=WNAME[lk.m];
  $('lkNum').placeholder='Please fill in '+WNAME[lk.m]+' account number';
  $('lkPwBox').classList.toggle('hidden-el',!!(user&&user.txPass));
  lkChk();
}
window.lkGroup=function(m){ lk.m=m; lkRender(); };
window.lkClose=function(){ $('linkWalletPage').classList.add('hidden-el'); dwSync(); };
window.lkChk=function(){
  var need=!(user&&user.txPass);
  var ok=$('lkName').value.trim().length>=3 && /^01\d{9}$/.test($('lkNum').value.trim());
  if(need) ok = ok && $('lkP1').value.length>=6 && $('lkP1').value===$('lkP2').value;
  $('lkSubmit').disabled=!ok;
};
window.lkGo=function(){
  var name=$('lkName').value.trim(), num=$('lkNum').value.trim(), need=!(user&&user.txPass);
  if(name.length<3) return toast('Enter your full legal name');
  if(!/^01\d{9}$/.test(num)) return toast('Enter a valid 11-digit account number');
  if(need){ if($('lkP1').value.length<6) return toast('Password must be at least 6 characters'); if($('lkP1').value!==$('lkP2').value) return toast('Passwords do not match'); }
  var ws=getW(lk.m);
  if(ws.length>=CFG.MAX_WALLETS) return toast('Maximum '+CFG.MAX_WALLETS+' wallets allowed');
  if(ws.some(function(w){ return String(w.num)===num; })) return toast('This account is already linked');
  if(!user.wallets) user.wallets={};
  ws.push({num:num,name:name,date:nowStr()}); user.wallets[lk.m]=ws;
  user.wallet={type:lk.m,num:num};
  if(need) user.txPass=$('lkP1').value;
  database.ref('users/'+user.phone).set(user);
  wd.m=lk.m; wd.sel[lk.m]=ws.length-1;
  lkClose(); wdRender(); toast('Linked successfully');
};

