/* ===== GX balance bridge: embedded games <-> app balance (user.balance, wager_left, Firebase) ===== */
var __gxSaveT=null;
window.gxBalGet=function(){try{return (typeof user!=='undefined'&&user)?(parseFloat(user.balance)||0):0}catch(e){return 0}};
window.gxBalFlush=function(){clearTimeout(__gxSaveT);try{if(typeof user!=='undefined'&&user&&user.phone)database.ref('users/'+user.phone).update({balance:user.balance,wager_left:user.wager_left||0})}catch(e){}};
window.gxBalSet=function(v){
  try{
    if(typeof user==='undefined'||!user)return;
    v=Math.max(0,Math.round((parseFloat(v)||0)*100)/100);
    var old=parseFloat(user.balance)||0;
    if(Math.abs(v-old)<0.005)return;
    if(v<old){var w=(parseFloat(user.wager_left)||0)-(old-v);user.wager_left=w<0?0:Math.round(w*100)/100}
    user.balance=v;
    try{updateUI()}catch(e){}
    clearTimeout(__gxSaveT);__gxSaveT=setTimeout(window.gxBalFlush,600);
  }catch(e){}
};
addEventListener('pagehide',function(){try{window.gxBalFlush()}catch(e){}});
document.addEventListener('visibilitychange',function(){if(document.hidden){try{window.gxBalFlush()}catch(e){}}});

