    TOG.forEach(function(t){ var v;
      if(t[0]==='hidePromo') v=c.hidePromo===true; else v=!(c.depositMethods&&c.depositMethods[t[0].slice(4)]===false);
      h+='<label style="display:flex;align-items:center;gap:8px;color:#ddd;font-size:13px;margin:6px 0;"><input type="checkbox" id="cfg_'+t[0]+'" '+(v?'checked':'')+'> '+t[1]+'</label>'; });
    var keys=[]; document.querySelectorAll('#page-home .gm[data-key]').forEach(function(g){ if(keys.indexOf(g.dataset.key)<0) keys.push(g.dataset.key); });
    if(keys.length){ var hg=c.hiddenGames||{}; h+='<div style="color:#aaa;font-size:12px;font-weight:700;margin:8px 0 4px;">Games (untick = hide)</div><div style="display:flex;flex-wrap:wrap;gap:6px;">';
      keys.forEach(function(k){ h+='<label style="background:#000;border:1px solid #333;border-radius:6px;padding:4px 8px;color:#ddd;font-size:11px;"><input type="checkbox" class="cfg_game" data-k="'+k+'" '+(hg[k]===true?'':'checked')+'> '+k+'</label>'; }); h+='</div>'; }
    var box=$('admCfgFields'); if(box) box.innerHTML=h;
